(4963492, 721904, 67152, '<td valign="top">very creepy image - and creepy in a good way</td>', 'very creepy image - and creepy in a good way', '2008-09-19 07:07:08.000000', NULL, 1),
(4963516, 722770, 67152, '<td valign="top">lovely b/w image - very dramatic scene - the image seems a bit unbalanced due to the horizon being not horizontal, but the details are great</td>', 'lovely b/w image - very dramatic scene - the image seems a bit unbalanced due to the horizon being not horizontal, but the details are great', '2008-09-19 07:10:55.000000', NULL, 1),
(4963519, 722898, 3746, '<td valign="top">love it - should do very well..</td>', 'love it - should do very well..', '2008-09-19 07:11:07.000000', NULL, 1),
(4963532, 721996, 3746, '<td valign="top">OH wow, this looks great - I hope the BW conversion was how you took the shot and not done in post-processing..</td>', 'OH wow, this looks great - I hope the BW conversion was how you took the shot and not done in post-processing..', '2008-09-19 07:12:54.000000', NULL, 1),
(4963533, 722077, 92296, '<td valign="top">The background works really really well - better than the child on the swing.  If you had panned and got the child in focus, this would be really good.</td>', 'The background works really really well - better than the child on the swing.  If you had panned and got the child in focus, this would be really good.', '2008-09-19 07:14:13.000000', NULL, 1),
(4963536, 721247, 3746, '<td valign="top">This isnt a knock on your photo, but if that is a genuine wedding shot then that is the scruffiest groom I have ever seen.  The shot would of benefitted from a longer lens to compress the couple a bit more, othersie this looks very snapshotty.</td>', 'This isnt a knock on your photo, but if that is a genuine wedding shot then that is the scruffiest groom I have ever seen.  The shot would of benefitted from a longer lens to compress the couple a bit more, othersie this looks very snapshotty.', '2008-09-19 07:14:43.000000', NULL, 1),
(4963537, 722819, 3746, '<td valign="top">strong composition</td>', 'strong composition', '2008-09-19 07:15:18.000000', NULL, 1),
(4963538, 721273, 92296, '<td valign="top">Nice lines and tone and a clever idea.  The street lamp(?) in the foreground is a bit of a distraction for me.</td>', 'Nice lines and tone and a clever idea.  The street lamp(?) in the foreground is a bit of a distraction for me.', '2008-09-19 07:16:24.000000', NULL, 1),
(4963545, 721755, 92296, '<td valign="top">I''m confused by the blurring of the numbers on the clock face.  I like the blurred hands and overall tone.</td>', 'I''m confused by the blurring of the numbers on the clock face.  I like the blurred hands and overall tone.', '2008-09-19 07:19:13.000000', NULL, 1),
(4963548, 722818, 92296, '<td valign="top">Very good capture of the car lights - perhaps deserving of a more interesting background?</td>', 'Very good capture of the car lights - perhaps deserving of a more interesting background?', '2008-09-19 07:20:47.000000', NULL, 1),
(4963551, 722010, 96574, '<td valign="top">ala wai..so pretty at night. nice exposure</td>', 'ala wai..so pretty at night. nice exposure', '2008-09-19 07:21:28.000000', NULL, 1),
(4963563, 721938, 92296, '<td valign="top">Nice idea that could''ve gone badly wrong, but I think this has worked out really well.  7</td>', 'Nice idea that could''ve gone badly wrong, but I think this has worked out really well.  7', '2008-09-19 07:23:16.000000', NULL, 1),
(4963587, 722887, 92296, '<td valign="top">Lighting is just right for this.  Face on the right looks a bit ''Dracula-like'' with a hint of fangs/blood - not sure if this is just an accident of blurring of teeth and lips.  7</td>', 'Lighting is just right for this.  Face on the right looks a bit ''Dracula-like'' with a hint of fangs/blood - not sure if this is just an accident of blurring of teeth and lips.  7', '2008-09-19 07:26:52.000000', NULL, 1),
(4963609, 722631, 92296, '<td valign="top">The arches of the bridge and their reflection are really good - wish they were even more prominent and not partially obscured.</td>', 'The arches of the bridge and their reflection are really good - wish they were even more prominent and not partially obscured.', '2008-09-19 07:29:11.000000', NULL, 1),
(4963619, 722635, 95579, '<td valign="top">Really nice image</td>', 'Really nice image', '2008-09-19 07:30:49.000000', NULL, 1),
(4963620, 722690, 95579, '<td valign="top">Actually makes me feel a tad motion sick if I look at the edges for too long!!  Nice shot</td>', 'Actually makes me feel a tad motion sick if I look at the edges for too long!!  Nice shot', '2008-09-19 07:32:09.000000', NULL, 1),
(4963622, 721817, 92296, '<td valign="top">Really like this.  Wish the lights on the bottom left didn''t catch my eye so much.</td>', 'Really like this.  Wish the lights on the bottom left didn''t catch my eye so much.', '2008-09-19 07:34:15.000000', NULL, 1),
(4963624, 721905, 92296, '<td valign="top">I had to scroll down to see the lower half of this and prefer it without the light (moon?) at the top. 7</td>', 'I had to scroll down to see the lower half of this and prefer it without the light (moon?) at the top. 7', '2008-09-19 07:35:37.000000', NULL, 1),
(4963625, 722631, 67152, '<td valign="top">really nice detail - too bad you appear to be a ghost in this image - or maybe that is the point....</td>', 'really nice detail - too bad you appear to be a ghost in this image - or maybe that is the point....', '2008-09-19 07:35:40.000000', NULL, 1),
(4963627, 722819, 92296, '<td valign="top">Best waterfall so far - nice contrast. 8</td>', 'Best waterfall so far - nice contrast. 8', '2008-09-19 07:37:47.000000', NULL, 1),
(4963628, 722635, 92296, '<td valign="top">This is so clever.  Really nice capture, tones and composition. 9</td>', 'This is so clever.  Really nice capture, tones and composition. 9', '2008-09-19 07:39:18.000000', NULL, 1),
(4963631, 721904, 92296, '<td valign="top">Great atmospherics - looks like it was drawn with charcoal. 8</td>', 'Great atmospherics - looks like it was drawn with charcoal. 8', '2008-09-19 07:43:13.000000', NULL, 1),
(4963632, 722551, 92296, '<td valign="top">Like the water and rocks - less keen on the branch bang in the middle. 6</td>', 'Like the water and rocks - less keen on the branch bang in the middle. 6', '2008-09-19 07:45:43.000000', NULL, 1),
(4963633, 722919, 92296, '<td valign="top">Just the right amount of detail on the car and love the way light picks out the lines.  Not sure about having the tail lights on - they rather catch the eye. 7</td>', 'Just the right amount of detail on the car and love the way light picks out the lines.  Not sure about having the tail lights on - they rather catch the eye. 7', '2008-09-19 07:48:24.000000', NULL, 1),
(4963637, 721996, 92296, '<td valign="top">Really like this, but think it could''ve been cropped even better - in slightly from the left and up a bit.  That way the gap between pillars on the left wouldn''t catch the eye and all the water would have a similar feel to it. 7.  Go on then, 8.</td>', 'Really like this, but think it could''ve been cropped even better - in slightly from the left and up a bit.  That way the gap between pillars on the left wouldn''t catch the eye and all the water would have a similar feel to it. 7.  Go on then, 8.', '2008-09-19 07:52:20.000000', NULL, 1),
(4963639, 722920, 92296, '<td valign="top">How did you do that?  7</td>', 'How did you do that?  7', '2008-09-19 07:53:58.000000', NULL, 1),
(4963655, 722688, 68769, '<td valign="top">Not normally into the abstract, but at the same time notice your shot is divided into 3 distinct areas. The lower area is smooth and flowing, mid section chaotic, upper portion abysmal, all on horizontal 3erd lines. I look forward to your comments after voting.</td>', 'Not normally into the abstract, but at the same time notice your shot is divided into 3 distinct areas. The lower area is smooth and flowing, mid section chaotic, upper portion abysmal, all on horizontal 3erd lines. I look forward to your comments after voting.', '2008-09-19 08:30:29.000000', NULL, 1),
(4963694, 722920, 68769, '<td valign="top">I like what you where going for here, the only thing that misses is the relation of sewing machine oil and a wine glass. Well captured all the same.</td>', 'I like what you where going for here, the only thing that misses is the relation of sewing machine oil and a wine glass. Well captured all the same.', '2008-09-19 09:03:44.000000', NULL, 1),
(4963697, 721938, 65234, '<td valign="top">Pretty cool effect.</td>', 'Pretty cool effect.', '2008-09-19 09:04:39.000000', NULL, 1),
(4963704, 722793, 65234, '<td valign="top">Nice and sharp and unexpectedly colorful.  The purple is quite a contrast to the rusted seat.  Bet the whole thing looks odd from a distance in what appears to be a peaceful natural context, but I know a distant subject doesn''t make a very good night shot.</td>', 'Nice and sharp and unexpectedly colorful.  The purple is quite a contrast to the rusted seat.  Bet the whole thing looks odd from a distance in what appears to be a peaceful natural context, but I know a distant subject doesn''t make a very good night shot.', '2008-09-19 09:08:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4963712, 721755, 65234, '<td valign="top">Nice idea; the dark band at the top of the clock separates the colorful bands from the clock without adding to the image concept IMO.  I think this would have been stronger with just the clock in the shot.</td>', 'Nice idea; the dark band at the top of the clock separates the colorful bands from the clock without adding to the image concept IMO.  I think this would have been stronger with just the clock in the shot.', '2008-09-19 09:14:00.000000', NULL, 1),
(4963717, 722837, 90495, '<td valign="top">How can this be a long exposure when the moon is perfectly in focus? You must have shot this at 1/250th or there abouts so this isn''t a long exposure. If it had been your moon wouldn''t be sharp.</td>', 'How can this be a long exposure when the moon is perfectly in focus? You must have shot this at 1/250th or there abouts so this isn''t a long exposure. If it had been your moon wouldn''t be sharp.', '2008-09-19 09:19:19.000000', NULL, 1),
(4963730, 721206, 90495, '<td valign="top">Hmm lay off the LSD. ;]</td>', 'Hmm lay off the LSD. ;]', '2008-09-19 09:24:24.000000', NULL, 1),
(4963741, 722777, 65234, '<td valign="top">I like your choice of subject with the stained glass windows, but it presented some technical challenges.  You got lots of detail in the sky, but I think I would have gone for a darker sky and exposed for the the lovely windows to give the image more impact.  There also appears to be some camera shake, as if you weren''t using a tripod or the tripod wasn''t completely stable.  Unless you wanted a shaky church as a political statement, but then I would expect the title to indicate that.</td>', 'I like your choice of subject with the stained glass windows, but it presented some technical challenges.  You got lots of detail in the sky, but I think I would have gone for a darker sky and exposed for the the lovely windows to give the image more impact.  There also appears to be some camera shake, as if you weren''t using a tripod or the tripod wasn''t completely stable.  Unless you wanted a shaky church as a political statement, but then I would expect the title to indicate that.', '2008-09-19 09:28:03.000000', NULL, 1),
(4963748, 722688, 65234, '<td valign="top">Certainly abstract; the patterns aren''t really grabbing me, though.</td>', 'Certainly abstract; the patterns aren''t really grabbing me, though.', '2008-09-19 09:29:33.000000', NULL, 1),
(4963762, 721382, 80904, '<td valign="top">I really like this effect. Well done. It comes to show that you dont need post processing to get a great shot. 10</td>', 'I really like this effect. Well done. It comes to show that you dont need post processing to get a great shot. 10', '2008-09-19 09:34:32.000000', NULL, 1),
(4963765, 722913, 65234, '<td valign="top">Early morning mist and slight breeze ruffling the flags.  Nice scene.  I''m not sure if the tilted horizon is intentional or not and the exposure was tricky (the best color and lighting to my eye is on the flags to the far left).</td>', 'Early morning mist and slight breeze ruffling the flags.  Nice scene.  I''m not sure if the tilted horizon is intentional or not and the exposure was tricky (the best color and lighting to my eye is on the flags to the far left).', '2008-09-19 09:35:19.000000', NULL, 1),
(4963767, 722480, 68769, '<td valign="top">Obscure title, I like it, I also like the capture. My only suggestion is maybe a step to the right would have calmed the blown out light while enhancing the water falling.</td>', 'Obscure title, I like it, I also like the capture. My only suggestion is maybe a step to the right would have calmed the blown out light while enhancing the water falling.', '2008-09-19 09:35:55.000000', NULL, 1),
(4963769, 721904, 80904, '<td valign="top">Man, I should have done this. Excellent photo. My guess this is Dave or Ian. Or someone else from Houston that I missed. Great shot. Hopefully this tree didnt fall on your house. I love the effect</td>', 'Man, I should have done this. Excellent photo. My guess this is Dave or Ian. Or someone else from Houston that I missed. Great shot. Hopefully this tree didnt fall on your house. I love the effect', '2008-09-19 09:36:33.000000', NULL, 1),
(4963771, 722487, 65234, '<td valign="top">Funny idea!  Considering this was minimal editing you pulled it off pretty well, but I have to admit I can see a ghostly body supporting the screaming head.</td>', 'Funny idea!  Considering this was minimal editing you pulled it off pretty well, but I have to admit I can see a ghostly body supporting the screaming head.', '2008-09-19 09:38:07.000000', NULL, 1),
(4963773, 722865, 65234, '<td valign="top">Some interesting light patterns here.  The little dark spots look like either the lens or sensor needed cleaning :-O</td>', 'Some interesting light patterns here.  The little dark spots look like either the lens or sensor needed cleaning :-O', '2008-09-19 09:39:41.000000', NULL, 1),
(4963774, 722925, 80904, '<td valign="top">LoL, this reminds me of that youtube joke that some guy did to his wife using the Darth Vader Mask and lightsaber. It was too funny. I was rolling down laughing. I stil laugh at the vid until this day. <br/>Here is a link to the video for your enjoyment<br/><a href="//www.guzer.com/videos/darth_vader_prank.php" rel="nofollow" target="_blank">Darth Vader scares the crap outta his wife</a></td>', 'LoL, this reminds me of that youtube joke that some guy did to his wife using the Darth Vader Mask and lightsaber. It was too funny. I was rolling down laughing. I stil laugh at the vid until this day. Here is a link to the video for your enjoymentDarth Vader scares the crap outta his wife', '2008-09-19 09:40:13.000000', NULL, 1),
(4963778, 722752, 65234, '<td valign="top">Nice exposure!  Horizon is a bit tilted and the composition''s serene simplicity draws my eye right there.</td>', 'Nice exposure!  Horizon is a bit tilted and the composition''s serene simplicity draws my eye right there.', '2008-09-19 09:43:46.000000', NULL, 1),
(4963779, 722755, 65234, '<td valign="top">Cute :-)</td>', 'Cute :-)', '2008-09-19 09:44:00.000000', NULL, 1),
(4963780, 722640, 68769, '<td valign="top">I have to say, your camera takes great pictures - Joking, fantastic capture..</td>', 'I have to say, your camera takes great pictures - Joking, fantastic capture..', '2008-09-19 09:44:06.000000', NULL, 1),
(4963782, 722592, 65234, '<td valign="top">Nice detail in the clouds and silhouette works for the foreground.</td>', 'Nice detail in the clouds and silhouette works for the foreground.', '2008-09-19 09:46:09.000000', NULL, 1),
(4963783, 721382, 65234, '<td valign="top">Nicely done :-)</td>', 'Nicely done :-)', '2008-09-19 09:46:52.000000', NULL, 1),
(4963786, 722640, 65234, '<td valign="top">Nicely exposed.  Hate to say it but it looks like you have some sensor dirt right there in the middle of your otherwise lovely sky :-O</td>', 'Nicely exposed.  Hate to say it but it looks like you have some sensor dirt right there in the middle of your otherwise lovely sky :-O', '2008-09-19 09:48:49.000000', NULL, 1),
(4963787, 722743, 65234, '<td valign="top">A scene familiar in cities the world over.  I really like the moving pigeon''s shadows and how clear they are in comparison to the the motion-blurred birds.</td>', 'A scene familiar in cities the world over.  I really like the moving pigeon''s shadows and how clear they are in comparison to the the motion-blurred birds.', '2008-09-19 09:50:37.000000', NULL, 1),
(4963789, 721488, 65234, '<td valign="top">Interesting idea for the challenge.  I think it might have been a bit stronger if you could have zoomed in to eliminate the coach and the sidelines.</td>', 'Interesting idea for the challenge.  I think it might have been a bit stronger if you could have zoomed in to eliminate the coach and the sidelines.', '2008-09-19 09:52:18.000000', NULL, 1),
