(4967543, 720932, 97225, '<td valign="top">Are those streaks stars? Gosh this must have been a long exposure.Turns night into day doesn''t it?</td>', 'Are those streaks stars? Gosh this must have been a long exposure.Turns night into day doesn''t it?', '2008-09-22 03:24:15.000000', NULL, 1),
(4967544, 722559, 97225, '<td valign="top">Lovely shot.</td>', 'Lovely shot.', '2008-09-22 03:24:40.000000', NULL, 1),
(4967545, 722927, 97225, '<td valign="top">Nice exposure.</td>', 'Nice exposure.', '2008-09-22 03:26:17.000000', NULL, 1),
(4967548, 721755, 97225, '<td valign="top">Effective.</td>', 'Effective.', '2008-09-22 03:27:07.000000', NULL, 1),
(4967550, 722567, 97225, '<td valign="top">Gosh, how did you take this?</td>', 'Gosh, how did you take this?', '2008-09-22 03:28:38.000000', NULL, 1),
(4967552, 722486, 97225, '<td valign="top">Beautiful photo. Love the black and gold.</td>', 'Beautiful photo. Love the black and gold.', '2008-09-22 03:29:37.000000', NULL, 1),
(4967554, 721817, 97225, '<td valign="top">This is just awesome.</td>', 'This is just awesome.', '2008-09-22 03:30:17.000000', NULL, 1),
(4967555, 722756, 97225, '<td valign="top">Brilliant color. Is that agolden ash? My in-laws had one by their clothes line too.</td>', 'Brilliant color. Is that agolden ash? My in-laws had one by their clothes line too.', '2008-09-22 03:32:58.000000', NULL, 1),
(4967557, 722755, 97225, '<td valign="top">Weird and effective.</td>', 'Weird and effective.', '2008-09-22 03:34:56.000000', NULL, 1),
(4967559, 721996, 97225, '<td valign="top">Beautiful quality to this shot.</td>', 'Beautiful quality to this shot.', '2008-09-22 03:36:02.000000', NULL, 1),
(4967560, 722010, 97225, '<td valign="top">Lovely photo.</td>', 'Lovely photo.', '2008-09-22 03:36:33.000000', NULL, 1),
(4967561, 722487, 97225, '<td valign="top">Oh wow! Excellent idea.</td>', 'Oh wow! Excellent idea.', '2008-09-22 03:37:28.000000', NULL, 1),
(4967562, 722757, 97225, '<td valign="top">Beautiful, beautiful and beautiful.</td>', 'Beautiful, beautiful and beautiful.', '2008-09-22 03:38:17.000000', NULL, 1),
(4967564, 722707, 97225, '<td valign="top">Great exposure.</td>', 'Great exposure.', '2008-09-22 03:38:43.000000', NULL, 1),
(4967568, 722929, 97225, '<td valign="top">Pity that something interrupts the bottom of the reflection. Maybe it would be better cropped at that point. Is cropping allowed?</td>', 'Pity that something interrupts the bottom of the reflection. Maybe it would be better cropped at that point. Is cropping allowed?', '2008-09-22 03:40:57.000000', NULL, 1),
(4967573, 722711, 97225, '<td valign="top">Beautiful shot. Is that exposure long enough?</td>', 'Beautiful shot. Is that exposure long enough?', '2008-09-22 03:43:53.000000', NULL, 1),
(4967575, 722818, 97225, '<td valign="top">Great shot.Love the passing light streaks.</td>', 'Great shot.Love the passing light streaks.', '2008-09-22 03:45:45.000000', NULL, 1),
(4967580, 721488, 97225, '<td valign="top">Your title explains it all. Nice shot.</td>', 'Your title explains it all. Nice shot.', '2008-09-22 03:48:14.000000', NULL, 1),
(4967582, 721104, 97225, '<td valign="top">Excellent shot.</td>', 'Excellent shot.', '2008-09-22 03:48:34.000000', NULL, 1),
(4967586, 722752, 97225, '<td valign="top">This does not really demonstrate long exposure to me, because it could be achieved with a short one.</td>', 'This does not really demonstrate long exposure to me, because it could be achieved with a short one.', '2008-09-22 03:50:39.000000', NULL, 1),
(4967590, 721191, 97225, '<td valign="top">Your panning is excellent.</td>', 'Your panning is excellent.', '2008-09-22 03:52:24.000000', NULL, 1),
(4967592, 722289, 97225, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2008-09-22 03:52:54.000000', NULL, 1),
(4967593, 721905, 97225, '<td valign="top">Great light trails.</td>', 'Great light trails.', '2008-09-22 03:53:27.000000', NULL, 1),
(4967596, 721382, 97225, '<td valign="top">That is really intriguing. I hope you share the explanation. It looks really cool.</td>', 'That is really intriguing. I hope you share the explanation. It looks really cool.', '2008-09-22 03:55:44.000000', NULL, 1),
(4967597, 722419, 97225, '<td valign="top">Beautiful shot. I love the soft, milky water.</td>', 'Beautiful shot. I love the soft, milky water.', '2008-09-22 03:56:27.000000', NULL, 1),
(4967603, 722906, 97225, '<td valign="top">Lovely shot. Bit of a pity about the wire, but you couldn''t edit it out.</td>', 'Lovely shot. Bit of a pity about the wire, but you couldn''t edit it out.', '2008-09-22 03:59:29.000000', NULL, 1),
(4967604, 722787, 97225, '<td valign="top">Lovely shot.</td>', 'Lovely shot.', '2008-09-22 03:59:51.000000', NULL, 1),
(4967611, 722563, 97225, '<td valign="top">Conveys the action nicely.</td>', 'Conveys the action nicely.', '2008-09-22 04:02:51.000000', NULL, 1),
(4967612, 722566, 97225, '<td valign="top">The little girl deserves a medal for sitting so still for so long. Charming shot.</td>', 'The little girl deserves a medal for sitting so still for so long. Charming shot.', '2008-09-22 04:04:34.000000', NULL, 1),
(4967613, 722806, 97225, '<td valign="top">Very effective.</td>', 'Very effective.', '2008-09-22 04:06:15.000000', NULL, 1),
(4967615, 722690, 97225, '<td valign="top">This makes me feel like I am moving. Great shot.</td>', 'This makes me feel like I am moving. Great shot.', '2008-09-22 04:07:38.000000', NULL, 1),
(4967616, 722912, 97225, '<td valign="top">Lovely colors. Great shot.</td>', 'Lovely colors. Great shot.', '2008-09-22 04:08:28.000000', NULL, 1),
(4967617, 722551, 97225, '<td valign="top">Beautiful water.</td>', 'Beautiful water.', '2008-09-22 04:08:54.000000', NULL, 1),
(4967618, 722819, 97225, '<td valign="top">Beautiful shot. Exposure and composition are great.</td>', 'Beautiful shot. Exposure and composition are great.', '2008-09-22 04:13:41.000000', NULL, 1),
(4967619, 722764, 97225, '<td valign="top">Great abstract.</td>', 'Great abstract.', '2008-09-22 04:14:11.000000', NULL, 1),
(4967620, 722920, 97225, '<td valign="top">Looks cool, but I don''t understand it.</td>', 'Looks cool, but I don''t understand it.', '2008-09-22 04:15:45.000000', NULL, 1),
