(4975352, 722309, 9462, '<td valign="top">Such a somber atmosphere but the two figures really bring out the intimacy of the moment.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=670651" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670651.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670651.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670651.jpg"/></a></td>', 'Such a somber atmosphere but the two figures really bring out the intimacy of the moment.', '2008-09-25 17:09:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4975664, 722635, 94265, '<td valign="top">I''d have cropped out that black uneven line on the right side, this almost looks like it was shot through a shower door. The idea is good though, I love that pouring from glass to glass, very effective.</td>', 'I''d have cropped out that black uneven line on the right side, this almost looks like it was shot through a shower door. The idea is good though, I love that pouring from glass to glass, very effective.', '2008-09-25 20:37:03.000000', NULL, 1),
(4975737, 721478, 76335, '<td valign="top">Beautiful colors, effective angle.</td>', 'Beautiful colors, effective angle.', '2008-09-25 21:27:09.000000', NULL, 1),
(4975739, 722912, 76335, '<td valign="top">No post processing? I want your camera. Beautiful!</td>', 'No post processing? I want your camera. Beautiful!', '2008-09-25 21:27:17.000000', NULL, 1),
(4975740, 722728, 76335, '<td valign="top">Delcious colors here. Nice exposure.</td>', 'Delcious colors here. Nice exposure.', '2008-09-25 21:27:19.000000', NULL, 1),
(4975741, 721704, 76335, '<td valign="top">Finally, something I can relate to. Nice abstract here, and one of the few BW shots I''ve seen in this challenge that works.</td>', 'Finally, something I can relate to. Nice abstract here, and one of the few BW shots I''ve seen in this challenge that works.', '2008-09-25 21:27:20.000000', NULL, 1),
(4975742, 722913, 76335, '<td valign="top">The muted colors are great. Well composed and good job choosing this time of day.</td>', 'The muted colors are great. Well composed and good job choosing this time of day.', '2008-09-25 21:27:21.000000', NULL, 1),
(4975743, 722278, 76335, '<td valign="top">Long exposure in many senses of the phrase. Nice job here.</td>', 'Long exposure in many senses of the phrase. Nice job here.', '2008-09-25 21:27:23.000000', NULL, 1),
(4975744, 722764, 76335, '<td valign="top">Now this is great! I tried this same kind of thing with my dashboard, but it didn''t work out.</td>', 'Now this is great! I tried this same kind of thing with my dashboard, but it didn''t work out.', '2008-09-25 21:27:24.000000', NULL, 1),
(4975745, 721880, 76335, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2008-09-25 21:27:25.000000', NULL, 1),
(4975746, 722481, 76335, '<td valign="top">Wonderful geometry here.</td>', 'Wonderful geometry here.', '2008-09-25 21:27:27.000000', NULL, 1),
(4975747, 721329, 76335, '<td valign="top">Abstract and very cool. Nice light show indeed. I love it!</td>', 'Abstract and very cool. Nice light show indeed. I love it!', '2008-09-25 21:27:29.000000', NULL, 1),
(4975748, 721065, 76335, '<td valign="top">One of the better "traffic trail" shots; the juxtaposition against the still bicycle adds another dimension.</td>', 'One of the better "traffic trail" shots; the juxtaposition against the still bicycle adds another dimension.', '2008-09-25 21:27:30.000000', NULL, 1),
(4975749, 722802, 76335, '<td valign="top">I love the pastel colors here. I would''ve made a mess of the colors in post-processing. I guess that''s the beauty of this challenge.</td>', 'I love the pastel colors here. I would''ve made a mess of the colors in post-processing. I guess that''s the beauty of this challenge.', '2008-09-25 21:27:34.000000', NULL, 1),
(4975750, 721191, 76335, '<td valign="top">The kin color looks somewhat unnaturalm but otherwise nice motion.</td>', 'The kin color looks somewhat unnaturalm but otherwise nice motion.', '2008-09-25 21:27:36.000000', NULL, 1),
(4975751, 721998, 76335, '<td valign="top">Great colors, nicely composed and exposed.</td>', 'Great colors, nicely composed and exposed.', '2008-09-25 21:27:41.000000', NULL, 1),
(4975752, 722717, 76335, '<td valign="top">Love the heels. I get the feeling your original intention was to capture a moving train, and you ended up with something better. Nice job!</td>', 'Love the heels. I get the feeling your original intention was to capture a moving train, and you ended up with something better. Nice job!', '2008-09-25 21:27:44.000000', NULL, 1),
(4975753, 722790, 76335, '<td valign="top">Interesting abstract. I''ll be curious to read about this one.</td>', 'Interesting abstract. I''ll be curious to read about this one.', '2008-09-25 21:27:45.000000', NULL, 1),
(4975754, 722758, 76335, '<td valign="top">Sharp, clear and well exposed. Nicely done.</td>', 'Sharp, clear and well exposed. Nicely done.', '2008-09-25 21:27:47.000000', NULL, 1),
(4975755, 722559, 76335, '<td valign="top">Nicely composed, beautiful colors.</td>', 'Nicely composed, beautiful colors.', '2008-09-25 21:27:48.000000', NULL, 1),
(4975756, 721817, 76335, '<td valign="top">Beautiful light show!</td>', 'Beautiful light show!', '2008-09-25 21:27:53.000000', NULL, 1),
(4975758, 722837, 76335, '<td valign="top">Nice. I like the simplicity of this.</td>', 'Nice. I like the simplicity of this.', '2008-09-25 21:27:54.000000', NULL, 1),
(4975759, 721905, 76335, '<td valign="top">Effective except maybe for the foreground shadow.</td>', 'Effective except maybe for the foreground shadow.', '2008-09-25 21:27:55.000000', NULL, 1),
(4975760, 721827, 76335, '<td valign="top">Great idea, beautiful colors.</td>', 'Great idea, beautiful colors.', '2008-09-25 21:27:57.000000', NULL, 1),
(4975761, 722690, 76335, '<td valign="top">Fun shot. Feels like I''m there with you!</td>', 'Fun shot. Feels like I''m there with you!', '2008-09-25 21:27:59.000000', NULL, 1),
(4975762, 722725, 76335, '<td valign="top">Nicely composed, but it''s hard to read the background -- at least to the extent that it''s recognized as something blowing around.</td>', 'Nicely composed, but it''s hard to read the background -- at least to the extent that it''s recognized as something blowing around.', '2008-09-25 21:28:29.000000', NULL, 1),
(4975763, 722140, 76335, '<td valign="top">Nice although the contrast is a bit flat. Of course, I have no idea what you could have done about it given the limitations of this challenge. Seems to lean to the right also.</td>', 'Nice although the contrast is a bit flat. Of course, I have no idea what you could have done about it given the limitations of this challenge. Seems to lean to the right also.', '2008-09-25 21:28:30.000000', NULL, 1),
(4975764, 722707, 76335, '<td valign="top">All those cranes are a bit distracting. Nothing you could have done about that, I realize, except maybe recompose.</td>', 'All those cranes are a bit distracting. Nothing you could have done about that, I realize, except maybe recompose.', '2008-09-25 21:28:32.000000', NULL, 1),
(4975765, 722752, 76335, '<td valign="top">Not a bad composition except that the horizon leans to the right.</td>', 'Not a bad composition except that the horizon leans to the right.', '2008-09-25 21:28:36.000000', NULL, 1),
(4975766, 722786, 76335, '<td valign="top">Needs more contrast in the sky to give it definition.</td>', 'Needs more contrast in the sky to give it definition.', '2008-09-25 21:28:42.000000', NULL, 1),
(4975767, 722077, 76335, '<td valign="top">Would be more effective if her (?) head or face at least were in focus.</td>', 'Would be more effective if her (?) head or face at least were in focus.', '2008-09-25 21:28:43.000000', NULL, 1),
(4975768, 722463, 76335, '<td valign="top">The sky''s not bad, but I think you need a sturdier tripod.</td>', 'The sky''s not bad, but I think you need a sturdier tripod.', '2008-09-25 21:28:47.000000', NULL, 1),
(4975769, 721938, 76335, '<td valign="top">This looks familiar. I''ve already been mistaken for you in the forums. Fun stuff.</td>', 'This looks familiar. I''ve already been mistaken for you in the forums. Fun stuff.', '2008-09-25 21:28:48.000000', NULL, 1),
(4975770, 722743, 76335, '<td valign="top">I''m not sure how this meets the challenge. That quibble aside, I do kind of like this...<br/> <br/>EDIT: I could have (or should have -- it was late) guessed that the long exposure was in the wings. In my opinion that''s the only way to shot pigeons, so nice job there. The shadow to the left is a slight distraction, but the black and white really works here, and I think that''s what caught my eye -- it really helps to keep the focus on the lines and depth and motion.</td>', 'I''m not sure how this meets the challenge. That quibble aside, I do kind of like this... EDIT: I could have (or should have -- it was late) guessed that the long exposure was in the wings. In my opinion that''s the only way to shot pigeons, so nice job there. The shadow to the left is a slight distraction, but the black and white really works here, and I think that''s what caught my eye -- it really helps to keep the focus on the lines and depth and motion.', '2008-09-25 21:28:49.000000', NULL, 1),
(4975771, 721488, 76335, '<td valign="top">Looks more out of focus than motion blurred.</td>', 'Looks more out of focus than motion blurred.', '2008-09-25 21:28:51.000000', NULL, 1),
(4975772, 722711, 76335, '<td valign="top">That''s a loaded title...</td>', 'That''s a loaded title...', '2008-09-25 21:28:55.000000', NULL, 1),
(4975940, 721704, 69733, '<td valign="top">JUST BEAUTIFUL!!! CONGRATULATIONS</td>', 'JUST BEAUTIFUL!!! CONGRATULATIONS', '2008-09-25 23:26:49.000000', NULL, 1),
(4975956, 722912, 59415, '<td valign="top">That is some amazing color for this challenge!</td>', 'That is some amazing color for this challenge!', '2008-09-25 23:39:24.000000', NULL, 1),
(4975957, 722924, 59415, '<td valign="top">Sweet speedy freeway!</td>', 'Sweet speedy freeway!', '2008-09-25 23:39:37.000000', NULL, 1),
(4975959, 721273, 59415, '<td valign="top">Sweet lighting.</td>', 'Sweet lighting.', '2008-09-25 23:39:55.000000', NULL, 1),
(4975960, 722640, 59415, '<td valign="top">Wow, that is some cool traffic shooting.</td>', 'Wow, that is some cool traffic shooting.', '2008-09-25 23:40:13.000000', NULL, 1),
(4975961, 722923, 59415, '<td valign="top">Wonderful cityscape!</td>', 'Wonderful cityscape!', '2008-09-25 23:40:27.000000', NULL, 1),
(4975962, 722786, 59415, '<td valign="top">Just a little bit dark for my taste, but looks like a nice scene!</td>', 'Just a little bit dark for my taste, but looks like a nice scene!', '2008-09-25 23:40:51.000000', NULL, 1),
(4975972, 722631, 59415, '<td valign="top">Um, I don''t know how to break this to you but...you might be a ghost.</td>', 'Um, I don''t know how to break this to you but...you might be a ghost.', '2008-09-25 23:54:09.000000', NULL, 1),
(4975973, 722419, 59415, '<td valign="top">Nice waterfall.  It might be just a bit dark, but it looks like a gem of a spot!</td>', 'Nice waterfall.  It might be just a bit dark, but it looks like a gem of a spot!', '2008-09-25 23:54:40.000000', NULL, 1),
(4975975, 722559, 59415, '<td valign="top">Wouldn''t that be cool if they hired a little guy to stand up there for real each day.</td>', 'Wouldn''t that be cool if they hired a little guy to stand up there for real each day.', '2008-09-25 23:55:09.000000', NULL, 1),
(4975978, 721062, 59415, '<td valign="top">I had to look at this for a few minutes because I thought it was 3 frogs!</td>', 'I had to look at this for a few minutes because I thought it was 3 frogs!', '2008-09-25 23:55:38.000000', NULL, 1),
(4975983, 722707, 59415, '<td valign="top">It looks like there might have been just a slight bit of movement maybe because the crain looks a little strange to me.  Maybe it is in the sharpening?</td>', 'It looks like there might have been just a slight bit of movement maybe because the crain looks a little strange to me.  Maybe it is in the sharpening?', '2008-09-25 23:56:49.000000', NULL, 1),
(4975985, 722921, 59415, '<td valign="top">Very nice effect with the lighting.</td>', 'Very nice effect with the lighting.', '2008-09-25 23:57:42.000000', NULL, 1),
(4975987, 722757, 59415, '<td valign="top">What a wonderful shot!</td>', 'What a wonderful shot!', '2008-09-25 23:58:17.000000', NULL, 1),
(4975988, 722803, 59415, '<td valign="top">Looks like a great spot for photos!</td>', 'Looks like a great spot for photos!', '2008-09-25 23:58:36.000000', NULL, 1),
(4975989, 721704, 59415, '<td valign="top">This is very cool.  Sort of abstract.</td>', 'This is very cool.  Sort of abstract.', '2008-09-25 23:58:51.000000', NULL, 1),
(4975990, 722481, 59415, '<td valign="top">It is very peaceful looking.  I think this would look nice framed.</td>', 'It is very peaceful looking.  I think this would look nice framed.', '2008-09-25 23:59:18.000000', NULL, 1),
(4975991, 722160, 59415, '<td valign="top">Lots of shades of green at work in this one, making it a tough shot to get.  I think you did well.</td>', 'Lots of shades of green at work in this one, making it a tough shot to get.  I think you did well.', '2008-09-25 23:59:59.000000', NULL, 1),
(4975992, 722162, 59415, '<td valign="top">I like all of the star lights.</td>', 'I like all of the star lights.', '2008-09-26 00:00:17.000000', NULL, 1),
(4975995, 722928, 77724, '<td valign="top">Might have worked for Bummer! too :)</td>', 'Might have worked for Bummer! too :)', '2008-09-26 00:01:03.000000', NULL, 1),
(4975996, 722289, 59415, '<td valign="top">Great sky, and a cool look to the tractor.  This is a spectacular shot for such minimal editing.</td>', 'Great sky, and a cool look to the tractor.  This is a spectacular shot for such minimal editing.', '2008-09-26 00:01:47.000000', NULL, 1),
(4975997, 722717, 59415, '<td valign="top">I think this shot would have been really cool if the guy on the left was not there.  It is still a very nice shot, but something about that guy bugs me.</td>', 'I think this shot would have been really cool if the guy on the left was not there.  It is still a very nice shot, but something about that guy bugs me.', '2008-09-26 00:02:31.000000', NULL, 1),
(4975999, 721905, 59415, '<td valign="top">Very pretty light shot.</td>', 'Very pretty light shot.', '2008-09-26 00:02:43.000000', NULL, 1),
(4976000, 722770, 59415, '<td valign="top">Wow, amazing.  I wish I could do stuff like this because it is just breath taking.</td>', 'Wow, amazing.  I wish I could do stuff like this because it is just breath taking.', '2008-09-26 00:03:04.000000', NULL, 1),
(4976001, 722728, 77724, '<td valign="top">Wow - truly amazing color for minimal.  Well done.</td>', 'Wow - truly amazing color for minimal.  Well done.', '2008-09-26 00:03:08.000000', NULL, 1),
(4976002, 721817, 59415, '<td valign="top">SWEET!</td>', 'SWEET!', '2008-09-26 00:03:12.000000', NULL, 1),
(4976003, 721886, 59415, '<td valign="top">This is so cool because it is so unusual!</td>', 'This is so cool because it is so unusual!', '2008-09-26 00:03:27.000000', NULL, 1),
(4976004, 722717, 77724, '<td valign="top">The title makes it.</td>', 'The title makes it.', '2008-09-26 00:03:43.000000', NULL, 1),
(4976005, 721191, 59415, '<td valign="top">Great motion on this.  Just perfect!</td>', 'Great motion on this.  Just perfect!', '2008-09-26 00:03:50.000000', NULL, 1),
(4976006, 722919, 59415, '<td valign="top">This probably will not score as high as it should.  This is just a classic scene that really you have to look at for a while to enjoy.  Very cool work.</td>', 'This probably will not score as high as it should.  This is just a classic scene that really you have to look at for a while to enjoy.  Very cool work.', '2008-09-26 00:04:26.000000', NULL, 1),
(4976007, 722925, 77724, '<td valign="top">Kinda static, did you try moving the light saber?</td>', 'Kinda static, did you try moving the light saber?', '2008-09-26 00:04:32.000000', NULL, 1),
(4976008, 722636, 59415, '<td valign="top">This would look great as a windows background.</td>', 'This would look great as a windows background.', '2008-09-26 00:04:48.000000', NULL, 1),
(4976009, 721382, 59415, '<td valign="top">Nice work, that is a cool idea.</td>', 'Nice work, that is a cool idea.', '2008-09-26 00:05:05.000000', NULL, 1),
(4976011, 722802, 59415, '<td valign="top">This is a great shot, but I would have like a little wider view to get the top of the coaster if possible.</td>', 'This is a great shot, but I would have like a little wider view to get the top of the coaster if possible.', '2008-09-26 00:05:35.000000', NULL, 1),
(4976012, 722666, 59415, '<td valign="top">I better get my shopping done!</td>', 'I better get my shopping done!', '2008-09-26 00:05:51.000000', NULL, 1),
(4976013, 721840, 59415, '<td valign="top">It has an abstract feel to it.</td>', 'It has an abstract feel to it.', '2008-09-26 00:06:13.000000', NULL, 1),
(4976015, 720932, 77724, '<td valign="top">lovely star trails</td>', 'lovely star trails', '2008-09-26 00:06:29.000000', NULL, 1),
(4976019, 722837, 59415, '<td valign="top">What a wonderful moon shot!</td>', 'What a wonderful moon shot!', '2008-09-26 00:07:31.000000', NULL, 1),
(4976021, 722451, 59415, '<td valign="top">Great colors, and somehow you got them to hold still!</td>', 'Great colors, and somehow you got them to hold still!', '2008-09-26 00:07:48.000000', NULL, 1),
(4976022, 722487, 59415, '<td valign="top">Ok, I don''t like being the one to give you bad news... but you might be a ghost dude.</td>', 'Ok, I don''t like being the one to give you bad news... but you might be a ghost dude.', '2008-09-26 00:08:26.000000', NULL, 1),
(4976023, 722140, 59415, '<td valign="top">It sort of looks like the Gargoyle is throwing up.</td>', 'It sort of looks like the Gargoyle is throwing up.', '2008-09-26 00:08:44.000000', NULL, 1),
(4976025, 721602, 59415, '<td valign="top">Great shot.  I love the waves at the upper right that have a mist to them.  Cool.</td>', 'Great shot.  I love the waves at the upper right that have a mist to them.  Cool.', '2008-09-26 00:09:04.000000', NULL, 1),
(4976028, 722224, 59415, '<td valign="top">That is a super colorful building!</td>', 'That is a super colorful building!', '2008-09-26 00:09:18.000000', NULL, 1),
(4976034, 722690, 59415, '<td valign="top">Nice ride.  I only own a Honda.</td>', 'Nice ride.  I only own a Honda.', '2008-09-26 00:11:03.000000', NULL, 1),
(4976035, 722906, 59415, '<td valign="top">I think this is a great shot.  You will get dinged for the wire though.</td>', 'I think this is a great shot.  You will get dinged for the wire though.', '2008-09-26 00:11:22.000000', NULL, 1),
(4976040, 722725, 59415, '<td valign="top">Very different.  I think this would look good framed in a hotel for some reason.</td>', 'Very different.  I think this would look good framed in a hotel for some reason.', '2008-09-26 00:14:19.000000', NULL, 1),
(4976046, 722295, 59415, '<td valign="top">I think that it is funny there is a fire extinguisher just hanging out there.  How did you manage to get on that side of the fence however?  That looks dangerous.</td>', 'I think that it is funny there is a fire extinguisher just hanging out there.  How did you manage to get on that side of the fence however?  That looks dangerous.', '2008-09-26 00:16:15.000000', NULL, 1),
(4976047, 721808, 59415, '<td valign="top">Great color.</td>', 'Great color.', '2008-09-26 00:16:34.000000', NULL, 1),
(4976048, 722861, 59415, '<td valign="top">This is a nice subtle image.  I didn''t know what to make of it at first, but I really do like it.</td>', 'This is a nice subtle image.  I didn''t know what to make of it at first, but I really do like it.', '2008-09-26 00:16:59.000000', NULL, 1),
(4976049, 721712, 59415, '<td valign="top">That is a great shot!</td>', 'That is a great shot!', '2008-09-26 00:18:06.000000', NULL, 1),
(4976054, 722818, 59415, '<td valign="top">It is the nations oldest beach shore resort theater.  I did not know that.</td>', 'It is the nations oldest beach shore resort theater.  I did not know that.', '2008-09-26 00:19:34.000000', NULL, 1),
(4976057, 722764, 59415, '<td valign="top">Nice.  It is so...computery.  Sort of like war games except with more colors.</td>', 'Nice.  It is so...computery.  Sort of like war games except with more colors.', '2008-09-26 00:20:09.000000', NULL, 1),
(4976119, 721908, 94265, '<td valign="top">Another ribbon! You gotta stop this, you''re making the rest of us look bad ;P Well done!</td>', 'Another ribbon! You gotta stop this, you''re making the rest of us look bad ;P Well done!', '2008-09-26 01:01:51.000000', NULL, 0),
(4976121, 722920, 45475, '<td valign="top">Magic stuff, congratulations!</td>', 'Magic stuff, congratulations!', '2008-09-26 01:03:04.000000', NULL, 0),
(4976123, 721904, 30982, '<td valign="top">My favorite of this challenge - moody, striking, very well done for straight from the camera!  Congrats on a great score, a top ten, and a new image in your top row!</td>', 'My favorite of this challenge - moody, striking, very well done for straight from the camera!  Congrats on a great score, a top ten, and a new image in your top row!', '2008-09-26 01:03:28.000000', NULL, 0),
(4976127, 722690, 40718, '<td valign="top">This was my blue ribbon pick.  Nice shot.</td>', 'This was my blue ribbon pick.  Nice shot.', '2008-09-26 01:07:14.000000', NULL, 0),
(4976128, 722920, 96614, '<td valign="top">Congratulations!!!  I added it to my favorites and will definitely be trying this shot myself in the near future!</td>', 'Congratulations!!!  I added it to my favorites and will definitely be trying this shot myself in the near future!', '2008-09-26 01:08:24.000000', NULL, 0),
(4976129, 721817, 96614, '<td valign="top">Congratulations!  Man! this is the second time you ribboned one up form me! Always have to beat me don''t you? hahaha Nice Shot!!!</td>', 'Congratulations!  Man! this is the second time you ribboned one up form me! Always have to beat me don''t you? hahaha Nice Shot!!!', '2008-09-26 01:09:48.000000', NULL, 0),
(4976130, 722920, 14476, '<td valign="top">congratulations, Tate, on a terrific entry.  Nice score, too.</td>', 'congratulations, Tate, on a terrific entry.  Nice score, too.', '2008-09-26 01:10:39.000000', NULL, 0),
